def filter_materialized_view(
        engine,
        view_name,
        schema="web",
        state_code=None,
        area=None,
        distance_grid=None,
        building=None,
        buildingfp=None,
        limit=None,
        keys=None,
):
    if schema is not None:
        view_name = "{}.{}".format(schema, view_name)
    if limit is None:
        limit = ""
    else:
        limit = " LIMIT {}".format(limit)

    filter_cond = ""

    if state_code is not None:
        key = "adm1_pcode"
        filter_cond = f" WHERE {view_name}.{key}='{state_code}'"

    if area is not None:
        key = "area_km2"
        if "WHERE" in filter_cond:
            filter_cond = filter_cond + f" AND {view_name}.{key} >= {area[0]} AND" \
                                        f" {view_name}.{key} <= {area[1]}"
        else:
            filter_cond = f" WHERE {view_name}.{key} >= {area[0]} AND {view_name}.{key} <= {area[1]}"

    if distance_grid is not None:
        key = "grid_dist_km"
        if "WHERE" in filter_cond:
            filter_cond = filter_cond + f" AND {view_name}.{key} >= {distance_grid[0]} AND" \
                                        f" {view_name}.{key} <= {distance_grid[1]}"
        else:
            filter_cond = f" WHERE {view_name}.{key} >= {distance_grid[0]} AND" \
                          f" {view_name}.{key} <= {distance_grid[1]}"

    if building is not None:
        key = "building_count"
        if "WHERE" in filter_cond:
            filter_cond = filter_cond + f" AND {view_name}.{key} >= {building[0]} AND" \
                                        f" {view_name}.{key} <= {building[1]}"
        else:
            filter_cond = f" WHERE {view_name}.{key} >= {building[0]} AND" \
                          f" {view_name}.{key} <= {building[1]}"

    if buildingfp is not None:
        key = "percentage_building_area"
        if "WHERE" in filter_cond:
            filter_cond = filter_cond + f" AND {view_name}.{key} >= {buildingfp[0]} AND" \
                                        f" {view_name}.{key} <= {buildingfp[1]}"
        else:
            filter_cond = f" WHERE {view_name}.{key} >= {buildingfp[0]} AND" \
                          f" {view_name}.{key} <= {buildingfp[1]}"

    if keys is None:
        columns = "*"
    else:
        if not isinstance(keys, str):
            columns = ", ".join(keys)
        else:
            columns = "COUNT({})".format(keys)
    with engine.connect() as con:
        query = 'SELECT {} FROM {}{}{};'.format(columns, view_name, filter_cond, limit)
        rs = con.execute(query)
        data = rs.fetchall()
    return data

def direct(query, content=True):
    output = None
    select = True
    query = agent.payloadDirect(query)
    threadData = getCurrentThreadData()

    if Backend.isDbms(DBMS.ORACLE) and query.startswith("SELECT ") and " FROM " not in query:
        query = "%s FROM DUAL" % query

    for sqlTitle, sqlStatements in SQL_STATEMENTS.items():
        for sqlStatement in sqlStatements:
            if query.lower().startswith(sqlStatement) and sqlTitle != "SQL SELECT statement":
                select = False
                break

    if select and not query.upper().startswith("SELECT "):
        query = "SELECT " + query

    logger.log(9, query)

    start = time.time()
    if not select:
        output = timeout(func=conf.dbmsConnector.execute, args=(query,), duration=conf.timeout, default=None)
    elif conf.hostname in kb.resumedQueries and query in kb.resumedQueries[conf.hostname] and "sqlmapoutput" not in query and "sqlmapfile" not in query:
        try:
            output = base64unpickle(kb.resumedQueries[conf.hostname][query][:-1])
        except:
            output = timeout(func=conf.dbmsConnector.select, args=(query,), duration=conf.timeout, default=None)

        infoMsg = "resumed from file '%s': " % conf.sessionFile
        infoMsg += "%s..." % getUnicode(output, UNICODE_ENCODING)[:20]
        logger.info(infoMsg)
    else:
        output = timeout(func=conf.dbmsConnector.select, args=(query,), duration=conf.timeout, default=None)
    threadData.lastQueryDuration = calculateDeltaSeconds(start)

    if output is None or len(output) == 0:
        return None
    elif content:
        if conf.hostname not in kb.resumedQueries or ( conf.hostname in kb.resumedQueries and query not in kb.resumedQueries[conf.hostname] ):
            dataToSessionFile("[%s][%s][%s][%s][%s]\n" % (conf.hostname, kb.injection.place, conf.parameters[kb.injection.place], query, base64pickle(output)))

        if len(output) == 1:
            if len(output[0]) == 1:
                out = list(output)[0][0]
                if isinstance(out, str):
                    out = utf8decode(out)
                return getUnicode(out, UNICODE_ENCODING)
            else:
                return list(output)
        else:
            return output
    else:
        for line in output:
            if line[0] in (1, -1):
                return True
            else:
                return False

