from sqlalchemy import text

def find_by_email_good(session, email):
    stmt = text('SELECT id FROM customers WHERE email = :email')
    return session.execute(stmt, {'email': email}).fetchall()

def _create_default_experiment(self, session):
        """
        MLflow UI and client code expects a default experiment with ID 0.
        This method uses SQL insert statement to create the default experiment as a hack, since
        experiment table uses 'experiment_id' column is a PK and is also set to auto increment.
        MySQL and other implementation do not allow value '0' for such cases.

        ToDo: Identify a less hacky mechanism to create default experiment 0
        """
        table = SqlExperiment.__tablename__
        default_experiment = {
            SqlExperiment.experiment_id.name: int(SqlAlchemyStore.DEFAULT_EXPERIMENT_ID),
            SqlExperiment.name.name: Experiment.DEFAULT_EXPERIMENT_NAME,
            SqlExperiment.artifact_location.name: str(self._get_artifact_location(0)),
            SqlExperiment.lifecycle_stage.name: LifecycleStage.ACTIVE
        }

        def decorate(s):
            if isinstance(s, str):
                return "'{}'".format(s)
            else:
                return "{}".format(s)

        # Get a list of keys to ensure we have a deterministic ordering
        columns = list(default_experiment.keys())
        values = ", ".join([decorate(default_experiment.get(c)) for c in columns])

        try:
            self._set_no_auto_for_zero_values(session)
            session.execute("INSERT INTO {} ({}) VALUES ({});".format(
                table, ", ".join(columns), values))
        finally:
            self._unset_no_auto_for_zero_values(session)

def _move_dangling_table(session, source_table: "Table", target_table_name: str, where_clause: str):
    dialect_name = session.get_bind().dialect.name

    delete_where = " AND ".join(
        f"{source_table.name}.{c.name} = d.{c.name}" for c in source_table.primary_key.columns
    )
    if dialect_name == "mssql":
        session.execute(
            text(f"select source.* into {target_table_name} from {source_table} as source {where_clause}")
        )
        session.execute(
            text(
                f"delete from {source_table} from {source_table} join {target_table_name} AS d ON "
                + delete_where
            )
        )
    else:
        if dialect_name == "mysql":
            # CREATE TABLE AS SELECT must be broken into two queries for  MySQL as the single query
            # approach fails when replication is enabled ("Statement violates GTID consistency")```
            session.execute(text(f"create table {target_table_name} like {source_table}"))
            session.execute(
                text(
                    f"INSERT INTO {target_table_name} select source.* from {source_table} as source "
                    + where_clause
                )
            )
        # Postgres and SQLite have the same CREATE TABLE a AS SELECT ... syntax
        else:
            session.execute(
                text(
                    f"create table {target_table_name} as select source.* from {source_table} as source "
                    + where_clause
                )
            )

        # But different join-delete syntax.
        if dialect_name == "mysql":
            session.execute(
                text(
                    f"delete {source_table} from {source_table} join {target_table_name} as d on "
                    + delete_where
                )
            )
        elif dialect_name == "sqlite":
            session.execute(
                text(
                    f"delete from {source_table} where ROWID in (select {source_table}.ROWID from "
                    f"{source_table} as source join {target_table_name} as d on {delete_where})"
                )
            )
        else:
            session.execute(
                text(f"delete from {source_table} using {target_table_name} as d where {delete_where}")
            )

