def _checkFileLength(self, localFile, remoteFile, fileRead=False):
        if Backend.isDbms(DBMS.MYSQL):
            lengthQuery = "SELECT LENGTH(LOAD_FILE('%s'))" % remoteFile

        elif Backend.isDbms(DBMS.PGSQL):
            if fileRead:
                lengthQuery = True
            else:
                lengthQuery = "SELECT LENGTH(data) FROM pg_largeobject WHERE loid=%d" % self.oid

        elif Backend.isDbms(DBMS.MSSQL):
            self.createSupportTbl(self.fileTblName, self.tblField, "VARBINARY(MAX)")
            inject.goStacked("INSERT INTO %s(%s) SELECT %s FROM OPENROWSET(BULK '%s', SINGLE_BLOB) AS %s(%s)" % (self.fileTblName, self.tblField, self.tblField, remoteFile, self.fileTblName, self.tblField));

            lengthQuery = "SELECT DATALENGTH(%s) FROM %s" % (self.tblField, self.fileTblName)

        localFileSize = os.path.getsize(localFile)

        logger.debug("checking the length of the remote file %s" % remoteFile)
        remoteFileSize = inject.getValue(lengthQuery, resumeValue=False, expected=EXPECTED.INT, charsetType=CHARSET_TYPE.DIGITS)
        sameFile = None

        if isNumPosStrValue(remoteFileSize):
            remoteFileSize = long(remoteFileSize)
            sameFile = False

            if localFileSize == remoteFileSize:
                sameFile = True
                infoMsg = "the local file %s and the remote file " % localFile
                infoMsg += "%s have the same size" % remoteFile
            elif remoteFileSize > localFileSize:
                infoMsg = "the remote file %s is larger than " % remoteFile
                infoMsg += "the local file %s" % localFile
            else:
                infoMsg = "the remote file %s is smaller than " % remoteFile
                infoMsg += "file '%s' (%d bytes)" % (localFile, localFileSize)

            logger.info(infoMsg)
        else:
            sameFile = False
            warnMsg = "it looks like the file has not been written, this "
            warnMsg += "can occur if the DBMS process' user has no write "
            warnMsg += "privileges in the destination path"
            logger.warn(warnMsg)

        return sameFile

def get_sql_filter_ops(cls, column, operator, dialect):
        import sqlalchemy as sa

        col = f"{column.class_.__tablename__}.{column.key}"

        # Use case-sensitive collation for MSSQL
        if dialect == MSSQL:
            column = column.collate("Japanese_Bushu_Kakusu_100_CS_AS_KS_WS")

        # Use non-binary ahead of binary comparison for runtime performance
        # Use non-binary ahead of binary comparison for runtime performance
        def case_sensitive_mysql_eq(value):
            return sa.text(f"{col} = :value AND BINARY {col} = :value").bindparams(
                sa.bindparam("value", value=value, unique=True)
            )

        def case_sensitive_mysql_ne(value):
            return sa.text(f"{col} != :value OR BINARY {col} != :value").bindparams(
                sa.bindparam("value", value=value, unique=True)
            )

        def case_sensitive_mysql_like(value):
            return sa.text(f"{col} LIKE :value AND BINARY {col} LIKE :value").bindparams(
                sa.bindparam("value", value=value, unique=True)
            )

        sql_filter_ops = {
            "=": case_sensitive_mysql_eq if dialect == MYSQL else column.__eq__,
            "!=": case_sensitive_mysql_ne if dialect == MYSQL else column.__ne__,
            "LIKE": case_sensitive_mysql_like if dialect == MYSQL else column.like,
            "ILIKE": column.ilike,
        }
        return sql_filter_ops[operator]

